"""Add real captures and exact captured/current passages to the shared reading page."""
from pathlib import Path
import json,re
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[3];BASE=HERE.relative_to(ROOT).as_posix()
def read(p):return json.loads(p.read_text(encoding='utf-8'))
def asset(p):return BASE+'/'+p
def item(title,description,report='SUMMARY.md',**kw):return dict(title=title,description=description,report=asset(report),**kw)
old=[r['map'] for r in read(HERE/'before/ada_run/em_plan.json')['plans'] if r.get('sequence')=='randomness']
new=read(HERE/'verification.json')['museum_spaces']
items=[item('Fourteen chapters, sixteen museum spaces','Five missing halls return. The two existing biome applications keep their places. This is verified sequence routing, not a claim that every physical crossing has been walked.',before=' → '.join(old),after=' → '.join(new),text_kind='museum route')]
items.append(item('10 PRINT: the walker and the visible mark agree','The original navigation raster opposed the rendered diagonal; changing a mark also left its stored value and search stale. The repair updates all three without moving the ant. The frozen original fails21 of34 checks; the corrected version passes34. Its final.md is unchanged.','opening/AUDIT.md'))
items.append(item('Fit the complete stacks; keep the experiment','All20 cubes and120 prisms remain. The common geometry fit creates a ten-metre display with a0.6m gap and floor-aligned starting faces. Controls remain full-size. Resuming now preserves the running clock. The chapter is unchanged.','middle/AUDIT.md',images=[asset('middle/rotate-before/stacks.png'),asset('middle/rotate-after/stacks.png')],captions=['Before · complete stacks overlap and extend through the hall.','Current · both complete stacks fit at the same common display scale.'],image_note='Actual Godot museum; same camera. This is an initial spatial fit, not a guarantee that later drift stays inside those bounds. The retained dark sphere remains visually close to the prisms.'))
items.append(item('Name the step law that is actually running','LONG STEP replaces LEVY on the instrument and in two chapter sentences. Frozen/current comparisons preserve30,000 sampled vectors. The detailed account of the cap, reflected endpoints and missing trail history stays.','middle/AUDIT.md',images=[asset('middle/walk-before/instrument.png'),asset('middle/walk-accepted/instrument.png')],captions=['Before · LEVY, seed777, mode2, step300.','Current · LONG STEP, same primary state and camera.'],image_note='Actual Godot museum. The primary terrarium is matched; the separately running background terrain was not seeded by this harness and differs. Existing button contrast remains a UI follow-up.'))
items.append(item('The Mushroom chapter regains its three encounters','The bed, arrival wardrobe and couture comparison now share primary status. Arrivals moves after the bed along the approach. All four existing artifacts remain. The substantial chapter keeps its repertoire and bodily questions.','middle/AUDIT.md',images=[asset('middle/mushroom-before/hall-plan.png'),asset('middle/mushroom-after/hall-plan.png')],captions=['Before · arrivals meets the visitor before the specimen bed.','Current · bed, then arrivals, then couture.'],image_note='Actual museum; matched elevated camera and seeded mushroom population. Tested standing capsules at all three controls are clear; this is not a headset walkthrough.'))
items.append(item('Make room for the feedback experiment','The original20m display crossed the restored architecture. The fitted4.8m display keeps the20m model domain and its rules. The comparison now has continuous floor, a clear plot and full-size controls; the sphere and ramp remain beside it.','ending/AUDIT.md',images=[asset('ending/before/museum/attract-overview.png'),asset('ending/verified/museum/attract-overview.png')],captions=['Before · oversized display passes through walls and adjacent space.','Current · fitted and repositioned comparison in the same museum.'],image_note='Same elevated camera, real Godot captures. The baseline demonstrates a defect, not a usable earlier hall. Architecture, material and display staging change; this pair is not an isolated test of a steering rule.'))
items.append(item('The same starts can make another world','ATTRACT and AVOID restart four walkers from the same seed and positions. Advance an equal number of fixed steps, then compare the marks. Pink shows current scent; white height retains accumulated visits; cyan marks current positions.','ending/AUDIT.md',images=[asset('ending/verified/museum/attract-side-standing.png'),asset('ending/verified/museum/avoid-side-standing.png')],captions=['Experiment A · ATTRACT, seed190919,300 steps.','Experiment B · AVOID, seed190919,300 steps.'],image_note='Two states of the current artifact, not software before/after. Same standing camera at world eye height1.7m. Different paths can consume later draws differently at a boundary. This single comparison is not a general theorem about the two laws.'))
for p in read(HERE/'text-changes.json'):
 name=Path(p['path']).parent.name
 items.append(item(name.replace('_',' '),p.get('reason','Align the existing chapter with the encounter and its place in the sequence.'),report='diffs/'+name+'.diff',before=p['old'],after=p['new'],text_kind='final.md'))
items.append(item('Preserved work and the next check','Nine chapters are byte-preserved; all133 artifact placements remain. One standalone Nature world is still deliberately ineligible. Full route/headset validation remains open: the runtime also reports a77-cell route warning in neighbouring Random Space, and two restored maps have older source-layer dimension mismatches. Investigate these before calling the complete route walkable. Noise follows after these physical-route questions.'))
for block in items:
 for key in ['title','description','image_note']:
  if key in block:
   block[key]=re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',block[key])
 if 'captions' in block:block['captions']=[re.sub(r'(?<=[A-Za-z])(?=\d)|(?<=\d)(?=[A-Za-z])',' ',s) for s in block['captions']]
record=dict(status='restored route; targeted encounter and prose repairs',summary='Chance does different work as it enters a palette, an eligible set, a step, a garment or a signal. This pass restores missing halls and missing comparisons, repairs specific behaviors, and preserves nine of fourteen chapters.',items=items)
target=ROOT/'doc/book/iterations/2026-09-19-review-comparison/randomness.json';target.write_text(json.dumps(record,indent=2,ensure_ascii=False)+'\n',encoding='utf-8')
print(target)
